import{freshState}from'./model.js';
import{lifestyleChoices,buildLifestyleInputs}from'./lifestyle-builder.js';
import{lifestyleIncomeRange}from'./lifestyle-story.js';
import{onetQuestions,onetResponseOptions,onetInstrument,scoreOnetInterest,riasecNames}from'./onet-assessment.js';
import{applyFictionalInterestProfile}from'./fictional-interest-profiles.js';
import{beginAutomaticFollowups083,saveAutomaticAnswer083}from'./automatic-followups-083.js';
import{explorerCareerQuestions}from'./open-explorer-087.js';
import{liveBoardData}from'./results-board-data.js';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'$'+Math.round(n/1000)+'k',s=freshState();s.profile.nickname='Sam · sample';const sample=freshState();applyFictionalInterestProfile(sample,'design-and-technology');let step=0,index=0,follow=0,data=null;const choices=s.guide.lifestyleBuilder.choices;for(const c of lifestyleChoices)choices[c.id]=['home','transport'].includes(c.id)?2:1;
const root=document.getElementById('journey');
function saveLife(){s.guide.lifestyleBuilder.complete=true;s.finance.lifestyle=buildLifestyleInputs(s.guide.lifestyleBuilder,s.finance.lifestyle);}
function presetProfiler(){s.profileJourney.officialInterest=structuredClone(sample.profileJourney.officialInterest);}
function sampleAnswer(q,item){if(item.careerId!=='web-interface-design')return{response:'unfamiliar',feedback:'unfamiliar',selected:[],source:'student',confidence:'high'};if(q.kind==='specific'||!q.options)return{response:'yes',source:'student',confidence:'high'};return{selected:q.options.filter(o=>o.careerIds?.includes('web-interface-design')).map(o=>o.id),source:'student',confidence:'high'};}
function render(){for(const b of document.querySelectorAll('[data-step]'))b.setAttribute('aria-current',Number(b.dataset.step)===step?'step':'false');if(step===0){saveLife();root.innerHTML=`<div class="target">Needed for this lifestyle: ${money(lifestyleIncomeRange(s.finance.lifestyle).minimum)} / year</div><div class="question"><h2>Picture your life</h2><p>Change Sam’s choices to see the income target update.</p><div class="sample-choices">${lifestyleChoices.map(c=>`<label>${h(c.question)}<select data-life="${c.id}">${c.options.map((o,i)=>`<option value="${i}" ${choices[c.id]===i?'selected':''}>${h(o.title)}</option>`).join('')}</select></label>`).join('')}</div><div class="actions"><button class="primary" data-action="next">Interest profiler →</button></div></div>`;}else if(step===1){const q=onetQuestions[index],a=s.profileJourney.officialInterest?.answers?.[q.id],done=scoreOnetInterest(s);root.innerHTML=`<div class="question"><p>${h(onetInstrument.name)} · ${index+1} of 60</p><div class="progress"><i style="width:${done.answered/60*100}%"></i></div><h2>How would you feel about this activity?</h2><h3>${h(q.text)}</h3><div class="answers">${onetResponseOptions.map(o=>`<button data-interest="${o.value}" aria-pressed="${a===o.value}">${h(o.label)}</button>`).join('')}</div><div class="actions"><button data-action="interest-back" ${index?'':'disabled'}>← Previous</button><button data-action="interest-next">Next →</button><button data-action="preset">Use Sam’s 60 sample answers</button>${done.complete?'<button class="primary" data-action="next">Targeted questions →</button>':''}</div><details><summary>All sample answers</summary><ol>${onetQuestions.map(q=>`<li>${h(q.text)} — <b>${h(onetResponseOptions.find(o=>o.value===sample.profileJourney.officialInterest.answers[q.id]).label)}</b></li>`).join('')}</ol></details><p class="note">${h(onetInstrument.attribution)} <a href="${onetInstrument.licenseURL}">License</a></p></div>`;}else if(step===2){if(!scoreOnetInterest(s).complete){root.innerHTML='<div class="question"><h2>Finish the interest profiler first</h2><button data-step="1">Back to profiler</button></div>';return;}beginAutomaticFollowups083(s);const round=s.explorer053.followupRound083,item=round.queue[follow];if(!item){root.innerHTML=`<div class="question"><h2>Targeted questions complete</h2><ol>${round.queue.map(item=>{const q=explorerCareerQuestions(item.careerId).find(q=>q.id===item.questionId),a=s.explorer053.professionAnswers[item.careerId]?.[q.id];return '<li><p>'+h(q.prompt)+'<br><b>'+h(a?.selected?.length?q.options.filter(o=>a.selected.includes(o.id)).map(o=>o.text).join(' · '):a?.response==='yes'?'I would like to learn this':a?.response==='no'?'This does not interest me':a?.response==='unsure'?'Unsure':'I need to learn more')+'</b></p></li>';}).join('')}</ol><button class="primary" data-action="next">See professions →</button></div>`;return;}const q=explorerCareerQuestions(item.careerId).find(q=>q.id===item.questionId),specific=q.kind==='specific'||!q.options;root.innerHTML=`<div class="question"><p>Targeted follow-up ${follow+1} of ${round.queue.length}</p><h2>${h(q.prompt)}</h2>${specific?`<div class="answers">${[['yes','I would like to learn this'],['no','This does not interest me'],['unsure','Unsure'],['unfamiliar','I need to learn more']].map(([v,l])=>`<button data-response="${v}">${l}</button>`).join('')}</div>`:`<div class="choices">${q.options.map(o=>`<label><input type="checkbox" value="${h(o.id)}" name="task"><span>${h(o.text)}</span></label>`).join('')}</div><div class="actions"><button class="primary" data-action="tasks">Continue →</button><button data-response="unfamiliar">I need to learn more</button></div>`}<div class="actions"><button data-action="sample-followup">Use Sam’s answer</button><button data-action="sample-rest">Use Sam’s remaining sample answers →</button></div><p class="note">Sam chooses interface-design activities. Unstated interests stay unknown. These are the live flow’s actual targeted questions.</p></div>`;}else{if(!scoreOnetInterest(s).complete||s.explorer053?.followupRound083?.cursor<s.explorer053?.followupRound083?.queue?.length){root.innerHTML='<div class="question"><h2>Complete the questionnaires first</h2><button data-step="1">Interest profiler</button><button data-step="2">Targeted questions</button></div>';return;}saveLife();data=liveBoardData(s);data.profiles[0].id='sample-journey';root.innerHTML=`<div class="actions"><h2>Sam’s professions</h2><button data-step="0">Adjust lifestyle</button><button data-step="1">Review interest answers</button></div><p>${data.profiles[0].supported.length} supported career${data.profiles[0].supported.length===1?'':'s'} · ${data.profiles[0].candidates.length} exploration candidates. Calculated from the demo answers using the live matcher.</p><iframe title="Sam’s results, earnings and education routes" id="demo-results" src="/results-board-frame.html"></iframe>`;document.getElementById('demo-results').onload=send;}}
function viewport(){const f=document.getElementById('demo-results');if(f)f.contentWindow.postMessage({type:'fieldguide-board-viewport',top:Math.max(0,-f.getBoundingClientRect().top)+16,height:Math.max(250,window.innerHeight-48)},location.origin);}
window.addEventListener('scroll',viewport,{passive:true});window.addEventListener('resize',viewport);
function send(){document.getElementById('demo-results')?.contentWindow.postMessage({type:'fieldguide-board-init',data,preview:true},location.origin);viewport();}
function answer(payload){const round=s.explorer053.followupRound083;saveAutomaticAnswer083(s,follow,payload);follow++;if(follow>=round.queue.length)step=3;render();}
document.addEventListener('change',e=>{if(e.target.dataset.life){choices[e.target.dataset.life]=Number(e.target.value);render();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.step!==undefined){step=Number(b.dataset.step);render();return;}if(b.dataset.interest){s.profileJourney.officialInterest??={...sample.profileJourney.officialInterest,answers:{}};s.profileJourney.officialInterest.answers[onetQuestions[index].id]=Number(b.dataset.interest);if(index<59)index++;render();return;}if(b.dataset.response){answer({response:b.dataset.response,source:'student',confidence:'high'});return;}switch(b.dataset.action){case'next':step++;if(step===2)follow=0;render();break;case'preset':presetProfiler();render();break;case'interest-back':index=Math.max(0,index-1);render();break;case'interest-next':index=Math.min(59,index+1);render();break;case'tasks':answer({selected:[...document.querySelectorAll('input[name=task]:checked')].map(e=>e.value),source:'student',confidence:'high'});break;case'sample-followup':{const item=s.explorer053.followupRound083.queue[follow],q=explorerCareerQuestions(item.careerId).find(q=>q.id===item.questionId);answer(sampleAnswer(q,item));break;}case'sample-rest':{const round=s.explorer053.followupRound083;while(follow<round.queue.length){const item=round.queue[follow],q=explorerCareerQuestions(item.careerId).find(q=>q.id===item.questionId);saveAutomaticAnswer083(s,follow,sampleAnswer(q,item));follow++;}step=3;render();break;}}});
window.addEventListener('message',e=>{const f=document.getElementById('demo-results');if(e.origin!==location.origin||e.source!==f?.contentWindow)return;if(e.data?.type==='fieldguide-board-ready')send();if(e.data?.type==='fieldguide-board-dialog')viewport();if(e.data?.type==='fieldguide-board-height'&&Number.isFinite(e.data.height))f.style.height=Math.max(900,Math.min(50000,e.data.height))+'px';if(e.data?.type==='fieldguide-board-navigate'){root.insertAdjacentHTML('beforeend','<p class="note" role="status">For a full personal career plan, choose “Start my own journey” above. Demo answers remain separate.</p>');}});render();
